<script setup lang="ts">
import { computed,ref } from 'vue'
import type { AlertRule } from '../domain/types'
import type { StockDesk } from '../composables/useStockDesk'
import { number,percent,trendClass,timeLabel } from '../domain/format'
import BaseDialog from './BaseDialog.vue'
import Icon from './Icon.vue'
const props=defineProps<{desk:StockDesk}>(),emit=defineEmits<{add:[rule?:AlertRule]}>()
const data=computed(()=>props.desk.data.value),enabled=computed(()=>data.value.alerts.filter(a=>a.enabled).length),deleting=ref<AlertRule|null>(null),clearConfirm=ref(false)
const timestamp=(time:number)=>new Date(time).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false})
</script>
<template><section class="alerts-view"><div class="page-heading"><div><div class="eyebrow">PRICE ALERTS</div><h1>价格提醒</h1><p>设置关键价位与涨跌幅，重要变化不再错过。</p></div><button class="button primary" data-testid="add-alert" @click="emit('add')"><Icon name="plus" :size="17"/>新建提醒</button></div>
 <div class="alert-info surface"><div class="alert-info-icon"><Icon name="bell" :size="24"/></div><div><strong>{{enabled}} 条规则监控中 <span>· 共 {{data.alerts.length}} 条</span></strong><p>仅在插件运行且持续刷新行情时工作。条件退出再进入、并经过冷却期后才会再次提醒。</p></div><span class="badge" :class="data.settings.refreshEnabled?'accent':'warning'">{{data.settings.refreshEnabled?'自动刷新已开启':'自动刷新已暂停'}}</span></div>
 <div v-if="!data.alerts.length" class="surface empty-state"><Icon name="bell" :size="38"/><h3>暂无提醒</h3><p>给关注的股票设置价格或涨跌幅阈值。</p><button class="button primary small" @click="emit('add')">创建第一条提醒</button></div>
 <div v-else class="alert-cards"><article v-for="rule in data.alerts" :key="rule.id" class="alert-card surface" :class="{disabled:!rule.enabled}"><div class="alert-card-heading"><div><h3>{{data.instruments[rule.symbol]?.name}}</h3><span class="mono muted">{{data.instruments[rule.symbol]?.code}} · {{data.instruments[rule.symbol]?.currency}}</span></div><button class="switch" :class="{on:rule.enabled}" role="switch" :aria-checked="rule.enabled" :aria-label="`${data.instruments[rule.symbol]?.name}提醒开关`" @click="desk.toggleAlert(rule.id)"><span/></button></div><div class="alert-condition"><span>{{rule.metric==='price'?'价格':'涨跌幅'}} {{rule.direction==='above'?'≥':'≤'}}</span><strong class="mono">{{number(rule.threshold)}}{{rule.metric==='changePercent'?'%':''}}</strong></div><div class="alert-current"><span>当前{{rule.metric==='price'?'价格':'涨跌幅'}}</span><strong class="mono" :class="trendClass(data.quoteCache[rule.symbol]?.changePercent)">{{rule.metric==='price'?number(data.quoteCache[rule.symbol]?.price):percent(data.quoteCache[rule.symbol]?.changePercent)}}</strong></div><div class="alert-card-footer"><span><Icon name="clock" :size="13"/>冷却 {{rule.cooldownMinutes}} 分钟 · {{!rule.enabled?'已暂停':rule.armed?'等待触发':'已触发，等待回落重置'}}</span><div><button class="icon-button" aria-label="编辑提醒" @click="emit('add',rule)"><Icon name="edit" :size="15"/></button><button class="icon-button" aria-label="删除提醒" @click="deleting=rule"><Icon name="trash" :size="15"/></button></div></div></article></div>
 <section class="surface alert-history"><div class="section-heading"><div><h2>触发记录 <span class="count-badge">{{data.alertEvents.length}}</span></h2><p>最近 200 条提醒，保存在本地</p></div><button v-if="data.alertEvents.length" class="text-button" @click="clearConfirm=true">清空记录</button></div><div v-if="!data.alertEvents.length" class="history-empty"><Icon name="clock" :size="20"/><span>尚无触发记录，满足规则时会显示在这里</span></div><div v-else class="history-list"><div v-for="event in data.alertEvents" :key="event.id" class="history-item"><div class="history-icon"><Icon name="bell" :size="16"/></div><div><strong>{{data.instruments[event.symbol]?.name}} <span class="mono">{{event.metric==='price'?'价格':'涨跌幅'}} {{event.direction==='above'?'≥':'≤'}} {{number(event.threshold)}}{{event.metric==='changePercent'?'%':''}}</span></strong><p>触发值 {{number(event.value)}}{{event.metric==='changePercent'?'%':''}} · 行情时间 {{timeLabel(event.exchangeTime)}}</p></div><time class="mono muted">{{timestamp(event.triggeredAt)}}</time></div></div></section>
 <div class="info-strip"><Icon name="info" :size="16"/><span>A 股行情超过 5 分钟、港美股超过 30 分钟，或时间异常时不触发提醒。港美股可能延时，本插件不承诺交易级时效。</span></div>
 <BaseDialog v-if="deleting||clearConfirm" :title="deleting?'删除提醒规则？':'清空触发记录？'" @close="deleting=null;clearConfirm=false"><div class="dialog-form"><p>{{deleting?'删除规则不会删除已有触发记录。':'所有本地提醒触发记录将被清空，此操作不可撤销。'}}</p><div class="dialog-actions"><button class="button subtle" @click="deleting=null;clearConfirm=false">取消</button><button class="button danger" @click="deleting?desk.deleteAlert(deleting.id):desk.clearAlertEvents();deleting=null;clearConfirm=false">确认{{deleting?'删除':'清空'}}</button></div></div></BaseDialog>
</section></template>
